// opencode.json (project) or ~/.config/opencode/opencode.json — nvHive as a provider
{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "nvhive": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "nvHive",
      "options": {
        "baseURL": "{base}",
        "apiKey": "{key}"
      },
      "models": {
        "auto": { "name": "nvHive auto-routing" },
        "safe": { "name": "nvHive local-only" }
      }
    }
  }
}

# Cursor → Settings → Models → OpenAI API Key
#   Override OpenAI Base URL: {base}
#   OpenAI API Key:           {key}
#   Add a custom model named "auto" (or "safe", "council") and select it.
# If Cursor's key check fails, try {base}/proxy as the base URL: the OpenAI-shaped
# model list is GET /v1/proxy/models (GET /v1/models keeps the nvHive envelope).
